const list = $input.first().json.rows || [];
const sevColor = { critical: '#7f1d1d', high: '#dc2626', medium: '#f59e0b', low: '#10b981', info: '#6b7280' };
const rows = list.map(a => {
  const color = sevColor[a.severity] || '#6b7280';
  const dev = a.deviation_pct !== null && a.deviation_pct !== undefined ? (a.deviation_pct > 0 ? '+' : '') + a.deviation_pct + '%' : '-';
  const baseline = a.baseline_value !== null && a.baseline_value !== undefined ? Number(a.baseline_value).toLocaleString('es-ES') : '-';
  const observed = a.observed_value !== null && a.observed_value !== undefined ? Number(a.observed_value).toLocaleString('es-ES') : '-';
  return '<tr>' +
    '<td><span style="background:' + color + ';color:white;padding:2px 8px;border-radius:3px;font-weight:bold">' + a.severity.toUpperCase() + '</span></td>' +
    '<td><b>' + (a.project_name || 'Sin proyecto') + '</b></td>' +
    '<td>' + a.entity_type + '<br><small style="color:#6b7280">' + a.anomaly_type + '</small></td>' +
    '<td><small>' + a.description + '</small></td>' +
    '<td>' + baseline + '</td>' +
    '<td>' + observed + '</td>' +
    '<td>' + dev + '</td>' +
    '</tr>';
}).join('');
const countBy = list.reduce((acc, a) => { acc[a.severity] = (acc[a.severity] || 0) + 1; return acc; }, {});
const html = '<h2>Anomalías detectadas</h2>' +
  '<p>Total nuevas: <b>' + list.length + '</b> &middot; ' +
  Object.entries(countBy).map(([k, v]) => '<span style="color:' + (sevColor[k] || '#000') + '"><b>' + v + ' ' + k + '</b></span>').join(' &middot; ') + '</p>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:12px">' +
  '<thead><tr style="background:#f3f4f6"><th>Sev.</th><th>Proyecto</th><th>Entidad</th><th>Descripción</th><th>Baseline</th><th>Observado</th><th>Desv.</th></tr></thead>' +
  '<tbody>' + rows + '</tbody></table>' +
  '<p style="font-size:11px;color:#6b7280">Revisar/descartar: POST /webhook/anomaly-review con {anomaly_id, status: "reviewed|accepted|dismissed|escalated", notes?}</p>';
return [{ json: { html_body: html, count: list.length, severity_summary: countBy } }];

